<?php $layout='layouts.app'; ?>
<h1>New communication</h1>
<div class="card" style="max-width:900px;margin-top:var(--space-4)"><div class="card-body"><form action="/communication" method="POST"><?= csrf() ?><div class="form-row"><div><label>Title</label><input name="title" maxlength="190" required value="<?= e(old('title','')) ?>"></div><div><label>Type</label><select name="type"><option value="announcement">Announcement</option><option value="notice">Notice</option><option value="message">Message</option></select></div></div><div style="margin-top:var(--space-4)"><label>Audience</label><select name="audience_type" id="audience_type"><option value="all">Everyone in the school</option><option value="role">Role</option><option value="class">Class</option><option value="stream">Class stream</option><option value="user">Individual user</option></select></div><div data-audience="role" hidden style="margin-top:var(--space-3)"><label>Role</label><select name="audience_role"><option value="">Select role</option><?php foreach($roles as $role): ?><option value="<?= e($role['name']) ?>"><?= e($role['name']) ?></option><?php endforeach; ?></select></div><div data-audience="class,stream" hidden style="margin-top:var(--space-3)"><label>Class</label><select name="audience_class_id"><option value="0">Select class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['name']) ?></option><?php endforeach; ?></select></div><div data-audience="stream" hidden style="margin-top:var(--space-3)"><label>Stream ID</label><input type="number" name="audience_stream_id" min="1"><p class="muted">Use the stream ID from class/stream setup.</p></div><div data-audience="user" hidden style="margin-top:var(--space-3)"><label>Recipient</label><select name="audience_user_id"><option value="0">Select user</option><?php foreach($users as $user): ?><option value="<?= (int)$user['id'] ?>"><?= e($user['email']) ?></option><?php endforeach; ?></select></div><div style="margin-top:var(--space-4)"><label>Message</label><textarea name="body" rows="10" required><?= e(old('body','')) ?></textarea></div><div style="margin-top:var(--space-5)"><button class="btn btn-primary" type="submit">Save draft</button> <a class="btn btn-outline" href="/communication">Cancel</a></div></form></div></div><script>const a=document.getElementById('audience_type');function syncAudience(){document.querySelectorAll('[data-audience]').forEach(el=>{el.hidden=!el.dataset.audience.split(',').includes(a.value);});}a.addEventListener('change',syncAudience);syncAudience();</script>
